L["Use Class Color"] = "Klassenfarbe verwenden"
L["Fill the bar with your class color instead of the color above."] = "Füllt die Leiste mit deiner Klassenfarbe statt mit der Farbe oben."
L["Bar Background"] = "Leistenhintergrund"
