L["Show Time"] = "Zeit anzeigen"
L["Show the countdown number, drawn by the game's own cooldown widget so it stays correct in combat."] = "Zeigt die Countdown-Zahl, gezeichnet vom spieleigenen Abklingzeit-Element, damit sie im Kampf korrekt bleibt."
L["Name Color"] = "Namensfarbe"
L["Time"] = "Zeit"
